ts_message("chunk #46 `conv_cor_wn_pop_boot` start")
# resample genome blocks with replacement and recompute the convergence
# correlation directly on each resampled dataset (no pre-computed statistics)

conv_cor_blocks_kmate <- create_blocks(gen0, chrom, pos, 15000, block_by = "snp", sep = "_")
win_ids <- unique(conv_cor_blocks_kmate$window)
W <- length(win_ids)
idx_lists <- split(seq_len(nrow(conv_cor_blocks_kmate)), conv_cor_blocks_kmate$window)

sites <- unique(gsub("_.*", "", colnames(hapfire)))

B <- 250
alpha <- 0.05

boot_samples <- NULL

for (a in sites) {
  print(paste("Site:", a))
  hap_site <- hapfire %>%
    dplyr::select(starts_with(paste(a, "_", sep = ""))) %>%
    collect()

  if (ncol(hap_site) < 2) {
    print("Too few columns. Skipping to next site...")
    next
  }

  # sort columns into generation order, then prepend the shared seedmix as t=0
  hap_site <- hap_site %>%
    relocate(all_of(sort(colnames(hap_site))))

  hap_site <- cbind(gen0$X0_0_0, hap_site)
  colnames(hap_site)[1] <- paste(a, "_0_0", sep = "")

  site_mat <- as.matrix(hap_site)
  rm(hap_site); gc()

  # generation labels computed on the cbind'd matrix: column indices below
  # refer to site_mat itself, so the gen0 column at position 1 is gen 0 and
  # every tray column keeps its own index
  gens <- as.integer(gsub("_", "", str_extract(colnames(site_mat), "_[0-9]_")))

  # per-interval pdiffs for this site (rows align with the block index lists)
  pdiffs_list <- vector("list", max(gens))
  for (t in sort(unique(gens[gens >= 1]))) {
    cols_t <- which(gens == t)
    if (t == 1) {
      pdiffs_list[[t]] <- site_mat[, cols_t, drop = FALSE] - site_mat[, 1]
    } else {
      reps_t <- gsub("^.*_", "", colnames(site_mat)[cols_t])
      cols_t1 <- match(paste(a, t - 1, reps_t, sep = "_"), colnames(site_mat))
      keep <- !is.na(cols_t1)
      pdiffs_list[[t]] <- site_mat[, cols_t[keep], drop = FALSE] - site_mat[, cols_t1[keep], drop = FALSE]
    }

    # drop zero-variance replicate columns; skip degenerate intervals
    keep_col <- apply(pdiffs_list[[t]], 2, function(x) {
      v <- var(x, na.rm = TRUE)
      is.finite(v) && v > 0
    })
    pdiffs_list[[t]] <- pdiffs_list[[t]][, keep_col, drop = FALSE]
    if (ncol(pdiffs_list[[t]]) < 2) pdiffs_list[[t]] <- NULL
  }

  site_boot <- vector("list", B * max(gens))
  k <- 0
  for (b in 1:B) {
    rows_index <- unlist(idx_lists[sample(win_ids, W, replace = TRUE)], use.names = FALSE)

    for (t in sort(unique(gens[gens >= 1]))) {
      if (is.null(pdiffs_list[[t]])) next
      pdiffs_boot <- pdiffs_list[[t]][rows_index, , drop = FALSE]

      # resampling cannot rescue a zero-variance column; re-apply the guard
      keep_col <- apply(pdiffs_boot, 2, function(x) {
        v <- var(x, na.rm = TRUE)
        is.finite(v) && v > 0
      })
      pdiffs_boot <- pdiffs_boot[, keep_col, drop = FALSE]
      if (ncol(pdiffs_boot) < 2) next

      conv_cor <- conv_cor_wn_pop(pdiffs_boot)
      k <- k + 1
      site_boot[[k]] <- data.frame(
        site = a,
        gen = t,
        b = b,
        S = nrow(pdiffs_boot),
        conv_cor_numer = conv_cor[1],
        conv_cor_denom = conv_cor[2]
      )
    }
  }
  boot_samples <- rbind(boot_samples, do.call(rbind, site_boot))
  rm(site_mat, pdiffs_list, site_boot); gc()
}

boot_samples <- boot_samples %>%
  mutate(conv_cor_boot = conv_cor_numer / conv_cor_denom)

# NOTE: added by /knitr-block — this chunk writes into the dated results
# directory but no included chunk creates it; mkdir once before the writes.
dir.create(paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today
), recursive = TRUE, showWarnings = FALSE)

fwrite(boot_samples, paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/conv_cor_wn_env_kmate_boot_samples.tsv"
), sep = "\t")

boot_summary <- boot_samples %>%
  group_by(site, gen) %>%
  summarize(lci = quantile(conv_cor_boot, alpha / 2),
            uci = quantile(conv_cor_boot, 1 - alpha / 2),
            conv_cor_mean = mean(conv_cor_boot))

fwrite(boot_summary, paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/conv_cor_wn_env_kmate_boot_summary.tsv"
), sep = "\t")
